   background: linear-gradient(0deg ,rgba(48,134,212,0.5) 50%,rgba(48,134,212,1) 0) center/5.8px 100%,
		linear-gradient(90deg,rgba(48,134,212,0.25) 50%,rgba(48,134,212,0.75) 0) center/100% 5.8px;
   background-repeat: no-repeat;
   animation: spinner-d3o0rx 1.2s infinite steps(12);
}

.spinner::before,
.spinner::after {
   content: "";
   grid-area: 1/1;
   border-radius: 50%;
   background: inherit;
   opacity: 0.915;
   transform: rotate(30deg);
}

.spinner::after {
   opacity: 0.83;
   transform: rotate(60deg);
}

